package com.hiretrack.web;
import com.hiretrack.model.*; import com.hiretrack.repo.*; import org.springframework.web.bind.annotation.*; import org.springframework.security.core.Authentication; import org.springframework.web.multipart.MultipartFile; import java.time.Instant; import java.io.IOException; import java.util.Map; import org.apache.pdfbox.pdmodel.PDDocument; import org.apache.pdfbox.text.PDFTextStripper;
@RestController @RequestMapping("/api/profile") public class ProfileController {private final ProfileRepository profiles;private final UserRepository users;public ProfileController(ProfileRepository p,UserRepository u){profiles=p;users=u;}
 @GetMapping public Profile get(Authentication a){User u=users.findByEmail(a.getName()).orElseThrow();return profiles.findByUserId(u.getId()).orElseGet(()->{Profile p=new Profile();p.userId=u.getId();return p;});}
 @PutMapping public Profile save(@RequestBody Profile p,Authentication a){User u=users.findByEmail(a.getName()).orElseThrow();Profile x=profiles.findByUserId(u.getId()).orElse(new Profile());x.userId=u.getId();x.headline=p.headline;x.bio=p.bio;x.skills=p.skills;x.resumeUrl=p.resumeUrl;x.updatedAt=Instant.now();return profiles.save(x);}
 @PostMapping(value="/resume", consumes="multipart/form-data") public Map<String,Object> upload(@RequestPart("file") MultipartFile file,Authentication a) throws IOException {if(file.isEmpty()) throw new IllegalArgumentException("Resume file is empty");if(file.getSize()>5_000_000) throw new IllegalArgumentException("Resume must be 5 MB or smaller");User u=users.findByEmail(a.getName()).orElseThrow();String text=extractText(file);Profile x=profiles.findByUserId(u.getId()).orElse(new Profile());x.userId=u.getId();x.resumeName=file.getOriginalFilename();x.resumeContent=text;x.resumeUrl="uploaded://"+file.getOriginalFilename();x.updatedAt=Instant.now();profiles.save(x);return Map.of("name",x.resumeName,"resumeUrl",x.resumeUrl,"autofill",Map.of("headline",extract(text,"headline"),"skills",extract(text,"skills"),"bio",text.length()>500?text.substring(0,500):text));}
 private String extractText(MultipartFile file) throws IOException {if(file.getOriginalFilename()!=null&&file.getOriginalFilename().toLowerCase().endsWith(".pdf")){try(PDDocument document=PDDocument.load(file.getBytes())){return new PDFTextStripper().getText(document);}}return new String(file.getBytes(),java.nio.charset.StandardCharsets.UTF_8);}
 private String extract(String text,String key){for(String line:text.split("\\R")){if(line.toLowerCase().startsWith(key+":"))return line.substring(key.length()+1).trim();}return "";}
}
